def binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def merge_sort(arr):
    if len(arr) > 1:
        mid = len(arr) // 2
        left_half = arr[:mid]
        right_half = arr[mid:]

        merge_sort(left_half)
        merge_sort(right_half)

        i = j = k = 0

        while i < len(left_half) and j < len(right_half):
            if left_half[i] < right_half[j]:
                arr[k] = left_half[i]
                i += 1
            else:
                arr[k] = right_half[j]
                j += 1
            k += 1

        while i < len(left_half):
            arr[k] = left_half[i]
            i += 1
            k += 1

        while j < len(right_half):
            arr[k] = right_half[j]
            j += 1
            k += 1

def find_closest_value(arr, target):
    sorted_arr = merge_sort(arr)
    index = binary_search(sorted_arr, target)

    if index != -1:
        return sorted_arr[index]

    closest_index = -1
    min_diff = float('inf')

    for i in range(len(sorted_arr)):
        diff = abs(sorted_arr[i] - target)
        if diff < min_diff:
            min_diff = diff
            closest_index = i

    return sorted_arr[closest_index]

