class Graph:
    def __init__(self):
        self.adj_list = {}

    def add_vertex(self, vertex):
        if vertex not in self.adj_list:
            self.adj_list[vertex] = []

    def add_edge(self, src, dest):
        if src in self.adj_list and dest in self.adj_list:
            self.adj_list[src].append(dest)
            self.adj_list[dest].append(src)

    def bfs_traversal(self, start_vertex):
        visited = set()
        queue = [start_vertex]
        visited.add(start_vertex)
        traversal_order = []

        while queue:
            current_vertex = queue.pop(0)
            traversal_order.append(current_vertex)

            for neighbor in self.adj_list[current_vertex]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return traversal_order

    def dfs_traversal(self, start_vertex):
        visited = set()
        traversal_order = []

        def dfs_util(vertex):
            visited.add(vertex)
            traversal_order.append(vertex)

            for neighbor in self.adj_list[vertex]:
                if neighbor not in visited:
                    dfs_util(neighbor)

        dfs_util(start_vertex)
        return traversal_order

