from pydantic import BaseModel, Field

class UserSchema(BaseModel):
    name: str = Field(min_length=2, max_length=50)
    age: int = Field(ge=18, le=99)

class AddressSchema(BaseModel):
    street: str = Field(min_length=5, max_length=100)
    city: str = Field(min_length=2, max_length=50)
    zip_code: str = Field(max_length=10)

class UserProfile(BaseModel):
    user: UserSchema
    address: AddressSchema
    phone_numbers: list[str] = Field(min_items=1, max_items=5)

def validate_profile(profile: UserProfile):
    if not profile.user.name.isalpha():
        raise ValueError("Name should only contain alphabetic characters")
    if profile.age < 21:
        raise ValueError("Age should be at least 21 for a valid profile")
    if not profile.address.zip_code.isdigit():
        raise ValueError("Zip code should only contain digits")
    if len(profile.phone_numbers) > 3:
        raise ValueError("Maximum 3 phone numbers allowed")

# Example usage
