import argparse

def parse_args():
    parser = argparse.ArgumentParser(description='Process command-line arguments for a simple file reader.')

    parser.add_argument('--file', required=True, help='Path to the input file')
    parser.add_argument('--encoding', default='utf-8', help='File encoding')
    parser.add_argument('--lines', type=int, help='Number of lines to read')

    args = parser.parse_args()
    return args

def read_file(args):
    try:
        with open(args.file, 'r', encoding=args.encoding) as f:
            if args.lines:
                for _ in range(args.lines):
                    print(f.readline(), end='')
            else:
                print(f.read())
    except FileNotFoundError:
        print(f"Error: File '{args.file}' not found.")
    except IOError:
        print(f"Error: Could not read file '{args.file}'.")

if __name__ == "__main__":
    args = parse_args()
    read_file(args)

from bs4 import BeautifulSoup
import requests

def parse_html_for_links(url):
    response = requests.get(url)
    soup = BeautifulSoup(response.content, 'html.parser')

    links = []
    for anchor in soup.find_all('a', href=True):
        link = anchor['href']
        if link.startswith('http'):
            links.append(link)

    return links

def filter_unique_links(links):
    unique_links = []
    seen = set()
    for link in links:
        if link not in seen:
            unique_links.append(link)
            seen.add(link)
    return unique_links

def main():
    url = "https://example.com"
    all_links = parse_html_for_links(url)
    unique_links = filter_unique_links(all_links)
    print(unique_links)

if __name__ == "__main__":
    main()

import random

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_into_tree(root, value):
    if root is None:
        return TreeNode(value)
    else:
        if value < root.value:
            root.left = insert_into_tree(root.left, value)
        else:
            root.right = insert_into_tree(root.right, value)
    return root

def in_order_traversal(root):
    if root:
        in_order_traversal(root.left)
        print(root.value, end=' ')
        in_order_traversal(root.right)

if __name__ == "__main__":
    tree_root = None
    values = [random.randint(1, 50) for _ in range(10)]
    for val in values:
        tree_root = insert_into_tree(tree_root, val)
    in_order_traversal(tree_root)

