import re

def extract_emails(text):
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    emails = re.findall(email_pattern, text)
    return emails

def replace_emails_with_placeholder(text):
    placeholder = "[REDACTED_EMAIL]"
    return re.sub(email_pattern, placeholder, text)

def main():
    input_text = "Please contact us at support@example.com or sales@example.org for further assistance."
    extracted_emails = extract_emails(input_text)
    print("Extracted Emails:", extracted_emails)

    redacted_text = replace_emails_with_placeholder(input_text)
    print("Redacted Text:", redacted_text)

if __name__ == "__main__":
    main()

class LibrarySystem:
    def __init__(self):
        self.books = [
            {"title": "Python Programming", "author": "Mark Summerfield", "available": True},
            {"title": "Effective Python", "author": "Brett Slatkin", "available": True},
            {"title": "Fluent Python", "author": "Luciano Ramalho", "available": False}
        ]

    def search_book(self, title):
        for book in self.books:
            if book["title"].lower() == title.lower():
                return book
        return None

    def borrow_book(self, title):
        book = self.search_book(title)
        if book and book["available"]:
            book["available"] = False
            return f"Book '{title}' borrowed successfully."
        elif book:
            return f"Book '{title}' is not available."
        else:
            return f"No book titled '{title}' found."

    def return_book(self, title):
        book = self.search_book(title)
        if book:
            book["available"] = True
            return f"Book '{title}' returned successfully."
        else:
            return f"No book titled '{title}' found."

library = LibrarySystem()
