class SingletonPattern:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(SingletonPattern, cls).__new__(cls)
            cls.value = "This is a singleton instance"
        return cls._instance

def factory_method(product_type):
    if product_type == "ProductA":
        return ProductA()
    elif product_type == "ProductB":
        return ProductB()
    else:
        raise ValueError("Invalid product type")

class ProductA:
    def operation(self):
        return "Product A operation"

class ProductB:
    def operation(self):
        return "Product B operation"

class ObserverPattern:
    def __init__(self):
        self._observers = []

    def add_observer(self, observer):
        self._observers.append(observer)

    def remove_observer(self, observer):
        self._observers.remove(observer)

    def notify_observers(self, message):
        for observer in self._observers:
            observer.update(message)

class ConcreteObserver:
    def update(self, message):
        print(f"Received message: {message}")

# Example usage
singleton = SingletonPattern()
print(singleton.value)

product_a = factory_method("ProductA")
print(product_a.operation())

