import argparse

def parse_args():
    parser = argparse.ArgumentParser(description="Process command-line arguments for file operations.")
    parser.add_argument('--file', type=str, required=True, help='The input file path')
    parser.add_argument('--operation', type=str, choices=['read', 'write'], required=True, help='Operation to perform on the file')
    parser.add_argument('--data', type=str, help='Data to write to the file if operation is "write"')
    args = parser.parse_args()
    return args

def read_file(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            print("File content:")
            print(content)
    except FileNotFoundError:
        print(f"The file {file_path} does not exist.")

def write_file(file_path, data):
    try:
        with open(file_path, 'w') as file:
            file.write(data)
            print(f"Data written to {file_path}")
    except IOError:
        print(f"An error occurred while writing to {file_path}")

def main():
    args = parse_args()

    if args.operation == 'read':
        read_file(args.file)
    elif args.operation == 'write':
        if not args.data:
            print("No data provided for writing.")
            return
        write_file(args.file, args.data)

if __name__ == "__main__":
    main()

