import os
from PIL import Image

def load_image(file_path):
    return Image.open(file_path)

def resize_image(image, width, height):
    return image.resize((width, height))

def crop_image(image, left, top, right, bottom):
    return image.crop((left, top, right, bottom))

def save_image(image, file_path):
    image.save(file_path)

def process_images(input_dir, output_dir, size=(128, 128)):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    for filename in os.listdir(input_dir):
        if filename.endswith(('.png', '.jpg', '.jpeg')):
            input_path = os.path.join(input_dir, filename)
            output_path = os.path.join(output_dir, filename)

            img = load_image(input_path)
            resized_img = resize_image(img, *size)
            cropped_img = crop_image(resized_img, 0, 0, 64, 64)
            save_image(cropped_img, output_path)

process_images('input_images', 'output_images')

