import random
import string

class NumberGuessingGame:
    def __init__(self):
        self.secret_number = random.randint(1, 100)
        self.attempts = 0

    def guess_number(self, user_guess):
        self.attempts += 1
        if user_guess < self.secret_number:
            return "Too low!"
        elif user_guess > self.secret_number:
            return "Too high!"
        else:
            return f"Congratulations! You guessed the number in {self.attempts} attempts."

def play_game():
    game = NumberGuessingGame()
    print("Welcome to the Number Guessing Game!")
    print("Guess a number between 1 and 100.")

    while True:
        try:
            user_input = input("Enter your guess: ")
            user_guess = int(user_input)
            result = game.guess_number(user_guess)
            print(result)

            if result.startswith("Congratulations"):
                play_again = input("Do you want to play again? (yes/no): ").lower()
                if play_again != "yes":
                    break
                game = NumberGuessingGame()
                print("New game started!")
        except ValueError:
            print("Invalid input. Please enter a valid number.")

if __name__ == "__main__":
    play_game()

