import os

def resize_image(input_path, output_path, width, height):
    if not os.path.exists(input_path):
        return "Input image does not exist."

    if width <= 0 or height <= 0:
        return "Width and height must be positive integers."

    try:
        from PIL import Image
        img = Image.open(input_path)
        resized_img = img.resize((width, height))
        resized_img.save(output_path)
        return "Image resized successfully."
    except Exception as e:
        return str(e)

def crop_image(input_path, output_path, x, y, width, height):
    if not os.path.exists(input_path):
        return "Input image does not exist."

    if x < 0 or y < 0 or width <= 0 or height <= 0:
        return "X, Y, width, and height must be non-negative integers."

    try:
        from PIL import Image
        img = Image.open(input_path)
        cropped_img = img.crop((x, y, x + width, y + height))
        cropped_img.save(output_path)
        return "Image cropped successfully."
    except Exception as e:
        return str(e)

if __name__ == "__main__":
    input_path = "input.jpg"
    output_path = "output.jpg"
    width = 800
    height = 600
    x = 100
    y = 50

    print(resize_image(input_path, output_path, width, height))
    print(crop_image(input_path, output_path, x, y, width, height))

def binary_search(arr, target):
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

def merge_sort(arr):
    if len(arr) > 1:
        mid = len(arr) // 2
        left_half = arr[:mid]
        right_half = arr[mid:]

        merge_sort(left_half)
        merge_sort(right_half)

        i = j = k = 0

        while i < len(left_half) and j < len(right_half):
            if left_half[i] < right_half[j]:
                arr[k] = left_half[i]
                i += 1
            else:
                arr[k] = right_half[j]
                j += 1
            k += 1

        while i < len(left_half):
            arr[k] = left_half[i]
            i += 1
            k += 1

        while j < len(right_half):
            arr[k] = right_half[j]
            j += 1
            k += 1

def find_duplicates(arr):
    sorted_arr = merge_sort(arr.copy())
    duplicates = []

    for i in range(1, len(sorted_arr)):
        if sorted_arr[i] == sorted_arr[i-1]:
            duplicates.append(sorted_arr[i])

    return duplicates

find_duplicates([4, 3, 6, 7, 3, 8, 9, 4])

