import random

def generate_board(size):
    return [[' ' for _ in range(size)] for _ in range(size)]

def print_board(board):
    for row in board:
        print(' | '.join(row))
        print('-' * (4 * len(row) - 1))

def check_winner(board, player):
    n = len(board)
    for i in range(n):
        if all(board[i][j] == player for j in range(n)) or all(board[j][i] == player for j in range(n)):
            return True
    if all(board[i][i] == player for i in range(n)) or all(board[i][n-i-1] == player for i in range(n)):
        return True
    return False

def is_full(board):
    return all(all(cell != ' ' for cell in row) for row in board)

def get_move(player, board):
    while True:
        try:
            move = input(f"Player {player}, enter your move (row col): ")
