class TreeNode:
    def __init__(self, value):
        self.value = value
        self.children = []

def add_child(parent, child):
    parent.children.append(child)

def print_tree(root, level=0):
    indent = "  " * level
    print(f"{indent}{root.value}")
    for child in root.children:
        print_tree(child, level + 1)

def find_node(root, target_value):
    if root.value == target_value:
        return root
    for child in root.children:
        found_node = find_node(child, target_value)
        if found_node:
            return found_node
    return None

def main():
    root = TreeNode("A")
    b = TreeNode("B")
    c = TreeNode("C")
    d = TreeNode("D")
    e = TreeNode("E")

    add_child(root, b)
    add_child(root, c)
    add_child(b, d)
    add_child(c, e)

    print("Tree structure:")
    print_tree(root)

    target = input("Enter the value of the node you want to find: ")
    node = find_node(root, target)
    if node:
        print(f"Found node with value {node.value}")
    else:
        print("Node not found")

