import numpy as np
from PIL import Image

def resize_and_crop_image(image_path, output_size=(256, 256)):
    image = Image.open(image_path)
    original_size = image.size

    if original_size[0] > output_size[0] or original_size[1] > output_size[1]:
        aspect_ratio = original_size[0] / original_size[1]
        new_width = int(aspect_ratio * output_size[1])

        if new_width > output_size[0]:
            new_width = output_size[0]
            new_height = int(new_width / aspect_ratio)
        else:
            new_height = output_size[1]

        resized_image = image.resize((new_width, new_height))
        left = (new_width - output_size[0]) // 2
        top = (new_height - output_size[1]) // 2
        right = left + output_size[0]
        bottom = top + output_size[1]
        cropped_image = resized_image.crop((left, top, right, bottom))
    else:
        cropped_image = image.resize(output_size)

    return cropped_image

def apply_image_filter(image_path, filter_type='blur'):
    image = Image.open(image_path)

    if filter_type == 'blur':
        filtered_image = image.filter(ImageFilter.BLUR)
    elif filter_type == 'sharpen':
        filtered_image = image.filter(ImageFilter.SHARPEN)
    elif filter_type == 'edge_enhance':
        filtered_image = image.filter(ImageFilter.EDGE_ENHANCE)
    else:
        raise ValueError("Unsupported filter type")

    return filtered_image

def save_processed_image(image, output_path):
    image.save(output_path)

