class Profile(BaseModel):
    bio: str = Field(min_length=10, max_length=500)
    interests: List[str] = Field(default_factory=list, min_items=1)

class ProfileUpdateRequest(BaseModel):
    bio: Optional[str]
    interests: Optional[List[str]]

def validate_profile(profile: Profile) -> bool:
    if not profile.bio or len(profile.bio) < 10:
        return False
    if not profile.interests or len(profile.interests) < 1:
        return False
    return True

def update_interests(profile: Profile, new_interests: List[str]) -> Profile:
    if not validate_profile(profile):
        raise ValueError("Invalid profile")
    updated_interests = set(new_interests) - {interest.lower() for interest in profile.interests}
    if not updated_interests:
        raise ValueError("No new interests provided")
    profile.interests.extend(updated_interests)
    return profile

