class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_into_tree(root, value):
    if root is None:
        return TreeNode(value)
    else:
        if value < root.value:
            root.left = insert_into_tree(root.left, value)
        else:
            root.right = insert_into_tree(root.right, value)
    return root

def in_order_traversal(root):
    result = []
    if root:
        result = in_order_traversal(root.left)
        result.append(root.value)
        result = result + in_order_traversal(root.right)
    return result

if __name__ == "__main__":
    root = None
    values = [8, 3, 10, 1, 6, 14, 4, 7, 13]
    for value in values:
        root = insert_into_tree(root, value)
    print(in_order_traversal(root))

from bs4 import BeautifulSoup

def parse_html_for_links(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    links = []
    for anchor in soup.find_all('a', href=True):
        link = anchor['href']
        if not link.startswith('#') and not link.startswith('javascript:'):
            links.append(link)
    return links

def extract_unique_links_from_webpage(url):
    import requests
    response = requests.get(url)
    if response.status_code == 200:
        links = parse_html_for_links(response.text)
        unique_links = list(set(links))
        return unique_links
    else:
        return []

if __name__ == "__main__":
    url = "https://example.com"
    links = extract_unique_links_from_webpage(url)
    print("Unique links found:", links)

