import argparse

def parse_config_file(file_path):
    config_data = {}
    with open(file_path, 'r') as file:
        lines = file.readlines()
        for line in lines:
            key, value = line.strip().split('=')
            config_data[key] = value
    return config_data

def main():
    parser = argparse.ArgumentParser(description='Parse configuration file and print settings')
    parser.add_argument('--file', type=str, required=True, help='Path to the configuration file')

    args = parser.parse_args()

    config = parse_config_file(args.file)
    for key, value in config.items():
        print(f'{key}: {value}')

if __name__ == '__main__':
