            if book["title"] == title and book["available"]:
                book["available"] = False
                print(f"Borrowed: {title}")
                return
        print(f"Sorry, {title} is not available.")

    def return_book(self, title):
        for book in self.books:
            if book["title"] == title and not book["available"]:
                book["available"] = True
                print(f"Returned: {title}")
                return
        print(f"Sorry, {title} was not borrowed.")

library = LibrarySystem()
library.display_books()
library.borrow_book("Python Crash Course")
library.return_book("Python Crash Course")
library.display_books()

class GraphNode:
    def __init__(self, value):
        self.value = value
        self.neighbors = []

def add_edge(node1, node2):
    node1.neighbors.append(node2)
    node2.neighbors.append(node1)

def breadth_first_search(start_node):
    visited = set()
    queue = [start_node]
    while queue:
        current = queue.pop(0)
        if current not in visited:
            visited.add(current)
            print(f"Visiting node: {current.value}")
            for neighbor in current.neighbors:
                if neighbor not in visited:
                    queue.append(neighbor)

# Example usage
node_a = GraphNode("A")
node_b = GraphNode("B")
node_c = GraphNode("C")

add_edge(node_a, node_b)
add_edge(node_b, node_c)

breadth_first_search(node_a)

async def unarchive_wallet_group(unarchive_wallet_group_requests: UnarchiveWalletGroupRequestContainer) -> List[GroupArchiveOrUnarchiveResponse]:
    if not armor_client:
        return [{"error": "Not logged in"}]
    try:
        result: List[GroupArchiveOrUnarchiveResponse] = await armor_client.unarchive_wallet_group(unarchive_wallet_group_requests)
        return result
    except Exception as e:
        return [{"error": str(e)}]
